-- Somente para `supabase db reset --local`. Nunca executar em cloud.
update private.security_config set allow_local_password_staff=true where singleton;
select j.id,s.name,s.position,s.terminal from public.jobs j cross join (values ('Inscrição',0,false),('Triagem',1,false),('Entrevista RH',2,false),('Entrevista com gestor',3,false),('Proposta',4,false),('Contratado',5,true),('Não selecionado',6,true)) as s(name,position,terminal);
